/* ETF ToGo · Brand v1.4: genuine standalone transparent asset, no cropped mockups */
.brandmark{display:grid;place-items:center;width:48px;height:48px;border:0;background:transparent;overflow:visible;border-radius:12px;flex-shrink:0}
.brandmark img{display:block;width:48px;height:48px;object-fit:contain;filter:drop-shadow(0 2px 4px #10397517)}
.brandname{letter-spacing:.3px}
.greeting h1{letter-spacing:-.5px}
.brand-feature{margin:18px 0;background:linear-gradient(115deg,#eef6ff,#f6fcff);border:1px solid #dbeaff;border-radius:18px;padding:16px}
.dark .brand-feature{background:#122848;border-color:#29496d}
.brand-feature h3{font-size:15px;margin:0 0 8px}
.brand-feature p{font-size:12px;line-height:1.65;color:var(--muted)}
.feature-badge{display:inline-block;border-radius:50px;font-size:10px;padding:4px 9px;background:#e1edfd;color:#185cd4;margin-bottom:10px}
.dark .feature-badge{background:#193b64;color:#abd3ff}
.feature-rows{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}
.feature-rows a{display:inline-flex;min-height:40px;padding:10px 12px;align-items:center;background:var(--card);border:1px solid var(--line);border-radius:12px;color:var(--accent);font-size:12px;font-weight:700}
.constituent-list{margin-top:13px}
.constituent-row{display:grid;grid-template-columns:minmax(0,1fr) 68px;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding:13px 0}
.constituent-row b{font-size:12px}
.constituent-row small{display:block;color:var(--muted);font-size:11px;margin-top:2px}
.constituent-row strong{text-align:right;font-size:14px;color:var(--ink)}
.constituent-row .progress{grid-column:1/-1;margin:0;height:5px}
.inline-danger{color:var(--warning);font-size:12px;padding:10px;background:var(--warnbg);border-radius:10px;margin-top:12px}
.info-box{padding:14px;background:var(--soft);border-radius:13px;color:var(--ink);font-size:12px;line-height:1.7;margin:12px 0}
.holding-view{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 12px}
.holding-view .button{min-height:40px}
.broker-list{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:16px 0}
.broker-tile{border:1px solid var(--line);background:var(--card);border-radius:12px;padding:14px;font-size:12px}
.broker-tile b{font-size:13px}.broker-tile small{display:block;color:var(--muted);margin-top:6px}
.import-note{font-size:11px;color:var(--muted);margin:8px 0}
@media(max-width:360px){.broker-list{grid-template-columns:1fr}.brandmark,.brandmark img{width:40px;height:40px}.brandname{font-size:15px}}

