function normalizeComponents(rows){if(!Array.isArray(rows)||!rows.length||rows.length>1000)return null;const seen=new Set(),out=[];let sum=0;for(const r of rows){const symbol=String(r.symbol||'').trim(),name=String(r.name||'').trim(),weight=Number(r.weight);if(!/^[A-Za-z0-9.\-]{1,15}$/.test(symbol)||seen.has(symbol)||!name||name.length>120||!Number.isFinite(weight)||weight<0||weight>100)return null;sum+=weight;seen.add(symbol);out.push({symbol,name,weight});}if(sum>110)return null;return out.sort((a,b)=>b.weight-a.weight);}
