function button(text,action,primary=false,more=''){return `<button class="button ${primary?'primary':''}" data-action="${action}" ${more}>${text}</button>`;}
function sourceNote(){return `<div class="data-note">${catalog?`名單日期 ${esc(catalog.sourceDate)} · 證交所上市國內股票 ETF${catalog.stale?' · 舊資料':''}<details><summary>資料範圍與分類方式</summary>尚未整合櫃買中心，不是全台 ETF 總數。主動／被動依官方類型，細分類為 App 規則，尚未逐檔人工覆核。${esc(catalog.warning||'')}</details>`:catalogError?`${esc(catalogError)} ${button('重新載入','reload-catalog')}`:'正在讀取官方名單…'}</div>`;}
function etfRow(e){return `<article class="etf-card" data-code="${esc(e.code)}"><a href="#etf/${esc(e.code)}"><div class="code">${esc(e.code)}</div><div class="etf-name">${esc(e.name)}</div><div class="tags"><span class="badge ${esc(e.category)}">${categoryLabel(e.category)}</span>${e.management==='active'?'':`<span class="badge">被動型</span>`}</div></a><a href="#etf/${esc(e.code)}" class="quote-slot" data-quote="${esc(e.code)}"><div class="q-price">—</div><div class="q-caption">尚未連接行情</div></a><button class="iconbtn ${favorites.includes(e.code)?'on':''}" data-action="favorite" data-code="${esc(e.code)}" aria-label="${favorites.includes(e.code)?'取消收藏':'收藏'} ${esc(e.code)}" aria-pressed="${favorites.includes(e.code)}">${icon('star')}</button></article>`;}
function totalCard(blue=false){const s=portfolioSummary(store(),records());return `<section class="card ${blue?'blue-card':'summary-card'}"><div class="cardhead"><a href="#holdings"><h3>我的資產總覽 ${icon('arrow')}</h3></a><button class="iconbtn" data-action="privacy" aria-label="${hideMoney?'顯示':'隱藏'}資產金額" aria-pressed="${hideMoney}">${icon('eye')}</button></div><div class="label">${s.complete?'持倉參考市值':'已填價格部位市值'}（TWD）</div><div class="amount" data-money>${money(s.value)}</div><div class="gain ${blue?'':tone(s.gain)}" data-money>${s.gain===null?'加入持有，開始記錄':`${s.gain>0?'▲ ':s.gain<0?'▼ ':''}${signed(s.gain)} 元 <span class="tiny">未實現損益</span>`}</div><div class="metrics"><div class="mini"><span>本月實收股息</span><b data-money>${money(s.current.received)}</b></div><div class="mini"><span>今年已領股息</span><b data-money>${money(s.yearReceived)}</b></div><div class="mini"><span>持有紀錄</span><b>${s.count} <span>筆</span></b></div></div><div class="fineprint">${s.count?`${s.knownCount}／${s.count} 筆有自填參考價格，非即時市值。`:'尚未新增持有，沒有填入任何示範資產。'}股息另列，不重複加進市值。</div></section>`;}
function cashRows(entries,limit=3){return entries.slice(0,limit).map(d=>`<a class="cash-line" href="#calendar/${esc(d.paymentDate)}"><span class="rowicon">${icon('calendar')}</span><span class="cash-text"><b>${esc(d.code)} ${esc(d.name)}</b><small>${esc(d.paymentDate)} · ${d.status==='received'?'已入帳':d.status==='announced'?'公告・自行登錄':'自行預估'}</small></span><strong data-money>${money(dividendAmount(d))}<span class="tiny"> 元</span></strong></a>`).join('');}
function home(){const s=portfolioSummary(store(),records());const followed=favorites.map(c=>records().find(e=>e.code===c)).filter(Boolean);return `<section class="greeting"><div><h1>你的 ETF，今天也整理好了。</h1><p>持有、配息、成分股，想看什麼一點就到。</p></div></section><div class="dashboard"><div>${totalCard()}<div class="quick-grid">${[['search','找一檔 ETF','list'],['wallet','我的持有','holdings'],['calendar','股息月曆','calendar'],['calc','試算工具','tools/compound']].map(([i,t,h])=>`<a class="quick" href="#${h}"><span class="quick-icon">${icon(i)}</span><span>${t}</span></a>`).join('')}</div>${!s.count?`<section class="card onboarding"><div class="illustration">${icon('wallet')}</div><div><h3>從你的第一檔 ETF 開始</h3><p>選擇 ETF，填入股數與總成本。<br>不用連接券商，也不用提供帳號密碼。</p>${button(icon('plus')+' 新增持有','add-holding',true)}</div></section>`:`<section class="card"><div class="cardhead"><h2>持有成本配置</h2><a href="#holdings/allocation">查看配置 ${icon('arrow')}</a></div>${allocation(s,3)}</section>`}</div><div><div class="section-head"><h2>接下來的股息</h2><a href="#calendar">看月曆 ${icon('arrow')}</a></div><section class="card">${s.upcoming.length?cashRows(s.upcoming):empty('目前沒有待入帳紀錄','登錄配息後，這裡會整理預定入帳時間。',`<a class="button smallbtn" href="#tools/dividends">記錄股息</a>`)}${s.overdue.length?`<a class="more-link" href="#notifications"><span class="text"><b>${s.overdue.length} 筆日期已到，待你確認</b><small>日期到達不代表已實際入帳。</small></span>${icon('arrow')}</a>`:''}</section><div class="section-head"><h2>${followed.length?'我的收藏':'探索 ETF'}</h2><a href="#${followed.length?'favorites':'list'}">查看全部 ${icon('arrow')}</a></div><div class="list-panel">${catalog?(followed.length?followed:records().filter(e=>['0050','00878','00991A'].includes(e.code))).slice(0,3).map(etfRow).join(''):'<div class="loading">正在讀取 ETF 名單…</div>'}</div>${sourceNote()}</div></div>`;}
function allocation(s,limit=Infinity){const entries=Object.entries(s.allocation).sort((a,b)=>b[1]-a[1]);if(!entries.length)return '<p class="small">新增持有後，顯示依成本計算的類別配置。</p>';return entries.slice(0,limit).map(([k,v])=>`<div class="allocation-row"><span>${categoryLabel(k)}</span><span data-money>${money(v)} 元 · ${s.cost?(v/s.cost*100).toFixed(1):'0.0'}%</span></div><div class="progress"><i style="width:${s.cost?v/s.cost*100:0}%"></i></div>`).join('')+'<p class="fineprint">依持倉成本，而非即時市值；不是成分股穿透分析。</p>';}
function list(){return `${title('探索 ETF',false,`<a class="iconbtn" href="#favorites" aria-label="我的收藏">${icon('star')}</a>`)}<label class="searchbox">${icon('search')}<input id="search" type="search" placeholder="輸入代碼或名稱，例如 0050" aria-label="搜尋 ETF" value="${esc(query)}"></label><div class="chips" id="filter-chips"></div><div class="list-controls"><span id="list-count"></span><label>排序 <select id="sort"><option value="code">代碼</option><option value="name">名稱</option></select></label></div><div class="list-panel" id="results"></div><div class="inline-actions" id="pagination"></div>${sourceNote()}`;}
function fillResults(){const target=document.querySelector('#results');if(!target)return;const q=query.trim().toLowerCase();const filtered=records().filter(e=>(category==='all'||e.category===category)&&`${e.code} ${e.name}`.toLowerCase().includes(q)).sort((a,b)=>String(a[sort]).localeCompare(String(b[sort]),'zh-TW'));const pages=Math.max(1,Math.ceil(filtered.length/10));listPage=Math.min(listPage,pages);document.querySelector('#filter-chips').innerHTML=[{id:'all',label:'全部'},...CATEGORIES].map(c=>`<button class="chip ${c.id===category?'selected':''}" data-action="filter" data-category="${c.id}" aria-pressed="${c.id===category}">${c.label}</button>`).join('');document.querySelector('#sort').value=sort;document.querySelector('#list-count').textContent=catalog?`${filtered.length} 檔 · 第 ${listPage}／${pages} 頁`:'名單載入中';target.innerHTML=!catalog?'<div class="loading">等待官方名單…</div>':filtered.length?filtered.slice((listPage-1)*10,listPage*10).map(etfRow).join(''):empty('沒有符合的已收錄 ETF','試著換個關鍵字，或選擇「全部」。');document.querySelector('#pagination').innerHTML=pages>1?`${button('上一頁','prev-page',false,listPage<=1?'disabled':'')}${button('下一頁','next-page',false,listPage>=pages?'disabled':'')}`:'';quote.routeChanged();}
function holdings(){const s=portfolioSummary(store(),records());return `${title('我的持有',false,button(icon('plus'),'add-holding',true,'aria-label="新增持有"'))}<div class="segmented"><button data-action="holding-tab" data-tab="holdings" class="${holdingTab==='holdings'?'selected':''}">持有部位</button><button data-action="holding-tab" data-tab="allocation" class="${holdingTab==='allocation'?'selected':''}">成本配置</button></div>${totalCard(true)}${holdingTab==='allocation'?`<section class="card"><h2>錢分配在哪些類型？</h2>${allocation(s)}</section>`:`<section class="card">${store().holdings.length?store().holdings.map(h=>`<article class="holding-row"><div><a href="#etf/${esc(h.code)}"><div class="code">${esc(h.code)}</div><div class="etf-name">${esc(h.name)}</div></a><div class="small" data-money>${money(h.shares)} 股 · 總成本 ${money(h.cost)}</div><div class="tiny">${h.priceDate?esc(h.priceDate)+' 自填參考價':'尚未填寫參考價'}</div><button class="button smallbtn" data-action="edit-holding" data-id="${esc(h.id)}" style="margin-top:9px">編輯</button></div><div class="right"><b data-money>${h.price===null?'—':money(h.shares*h.price)}</b><p class="small ${h.price===null?'':tone(h.shares*h.price-h.cost)}" data-money>${h.price===null?'尚無估值':signed(h.shares*h.price-h.cost)+' 元'}</p><span class="tiny">參考市值／未實現損益</span></div></article>`).join(''):empty('還沒有持有紀錄','新增一檔，你的資產就會開始出現在這裡。')}</section>`}<div class="inline-actions">${button(icon('plus')+' 新增持有','add-holding',true)}<a class="button" href="#tools/portfolio">完整管理／匯出</a></div><div class="data-note">目前是持倉快照，非買賣流水帳。已實現損益與歷史績效未計算。</div>`;}
function calendar(){const monthStr=`${calYear}-${String(calMonth).padStart(2,'0')}`;const entries=store().dividends.filter(d=>d.paymentDate.startsWith(monthStr));const shown=calendarTab==='history'?store().dividends.filter(d=>d.status==='received').sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate)):entries.filter(d=>d.paymentDate===selectedDay);const received=entries.filter(d=>d.status==='received').reduce((a,d)=>a+dividendAmount(d),0);return `${title('股息月曆',true,`<a class="iconbtn" href="#tools/dividends" aria-label="新增股息紀錄">${icon('plus')}</a>`)}<div class="segmented"><button data-action="calendar-tab" data-tab="calendar" class="${calendarTab==='calendar'?'selected':''}">入帳月曆</button><button data-action="calendar-tab" data-tab="history" class="${calendarTab==='history'?'selected':''}">已領紀錄</button></div>${calendarTab==='calendar'?`<section class="card"><div class="calendar-head"><button class="iconbtn" data-action="prev-month" aria-label="上個月" ${calYear===1900&&calMonth===1?'disabled':''}>${icon('back')}</button><h2>${calYear} 年 ${calMonth} 月</h2><button class="iconbtn" data-action="next-month" aria-label="下個月" ${calYear===2200&&calMonth===12?'disabled':''}>${icon('arrow')}</button></div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(d=>`<div class="weekday">${d}</div>`).join('')}${calendarCells(calYear,calMonth).map(d=>d?`<button class="day ${d===selectedDay?'selected':''} ${d===today?'today':''}" data-action="day" data-date="${d}" aria-label="${d}" aria-pressed="${d===selectedDay}">${Number(d.slice(-2))}<span class="dots">${[...new Set(entries.filter(e=>e.paymentDate===d).map(e=>e.status))].map(s=>`<i class="dot ${s}"></i>`).join('')}</span></button>`:'<span></span>').join('')}</div><div class="legend"><span><i class="dot"></i>已入帳</span><span><i class="dot announced"></i>公告・自行登錄</span><span><i class="dot planned"></i>自行預估</span></div><div class="cash-line" style="margin-top:10px"><span class="small">本月實際已領</span><strong data-money>${money(received)} 元</strong></div></section>`:''}<div class="section-head"><h2>${calendarTab==='history'?'實收股息紀錄':esc(selectedDay)}</h2><a href="#tools/dividends">管理紀錄 ${icon('arrow')}</a></div>${shown.length?shown.map(d=>`<a class="calendar-event" style="display:block" href="#tools/dividends"><b>${esc(d.code)} ${esc(d.name)}</b><p>${esc(d.paymentDate)} · ${d.status==='received'?'實際入帳':d.status==='announced'?'已公告・自行登錄':'自行預估'} <strong data-money>${money(dividendAmount(d))} 元</strong></p>${d.exDate?`<p>除息日 ${esc(d.exDate)}</p>`:''}</a>`).join(''):empty(calendarTab==='history'?'還沒有實收紀錄':'這天沒有已登錄的入帳','這不代表市場沒有配息；本版由你登錄配息資訊。',`<a class="button primary" href="#tools/dividends">${icon('plus')} 記錄股息</a>`)}<p class="data-note">以「入帳日」安排現金流，除息日另外標示。公告尚未自動同步。</p>`;}
function detail(code){const e=records().find(e=>e.code===code);if(!e)return `${title(code||'ETF 詳情')}${empty(catalog?'此代碼未在目前資料範圍':'正在載入 ETF 名單','已保存的持有不會因此被刪除。',`<a class="button" href="#list">回探索</a>`)}${sourceNote()}`;const dv=store().dividends.filter(d=>d.code===code);return `${title(esc(e.code),true,`<button class="iconbtn ${favorites.includes(code)?'on':''}" data-action="favorite" data-code="${code}" aria-label="收藏 ${code}">${icon('star')}</button>`)}<div class="detail-hero"><h2>${esc(e.name)}</h2><p class="small">${categoryLabel(e.category)} · ${e.management==='active'?'主動管理':'追蹤指數'}</p><div class="quote-slot" data-quote="${code}"></div></div><div class="segmented">${[['overview','總覽'],['components','成分股'],['dividend','配息'],['info','基金資訊']].map(([v,t])=>`<button data-action="detail-tab" data-tab="${v}" class="${detailTab===v?'selected':''}">${t}</button>`).join('')}</div>${detailTab==='overview'?`<section class="card"><h3>價格與績效</h3><div class="chart-empty">${icon('chart')}<p>歷史走勢資料尚未接入</p><small>不以示意線條代替真實績效。</small></div><div class="details-grid"><div class="detail-field"><span>管理方式</span>${e.management==='active'?'主動式':'被動式'}</div><div class="detail-field"><span>上市日期</span>${esc(e.listingDate||'待確認')}</div><div class="detail-field"><span>淨值／折溢價</span>尚未接入</div><div class="detail-field"><span>基金費用率</span>尚未接入</div></div></section>`:detailTab==='components'?constituentsPanel(code):detailTab==='dividend'?`<section class="card"><h3>這檔 ETF 的配息記錄</h3>${dv.length?cashRows(dv.sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate)),20):empty('還沒有配息紀錄','這裡顯示你自行登錄的股息，不是官方配息歷史。',`<a class="button" href="#tools/dividends">記錄股息</a>`)}</section>`:`<section class="card"><h3>官方基本資料</h3><p class="small" style="margin-top:12px">${esc(e.fullName||e.name)}</p><div class="detail-field" style="margin:14px 0"><span>追蹤指數</span>${esc(e.index||'不適用／未提供')}</div><div class="detail-field"><span>分類依據（App 規則）</span>${esc(e.classificationBasis||'待分類')}</div><p class="data-note">資料日期 ${esc(e.sourceDate||catalog.sourceDate)}</p><a class="button" target="_blank" rel="noopener noreferrer" href="https://www.twse.com.tw/zh/products/securities/etf/products/list.html">官方查證 ${icon('arrow')}</a></section>`}<div class="inline-actions">${button(icon('plus')+' 記錄持有','add-holding',true,`data-code="${code}"`)}${button(icon('compare')+(comparison.includes(code)?' 已加入比較':' 加入比較'),'compare',false,`data-code="${code}"`)}</div><p class="data-note">行情依個人連線提供；配息與歷史績效資料尚未同步。以上不構成買賣建議。</p>`;}
function compareOverlapPanel(){
 const codes=comparison.slice(0,3),available=codes.filter(code=>constituentData.has(code)),missing=codes.filter(code=>!constituentData.has(code));
 if(codes.length<2)return '';
 const holdings=new Map();
 for(const code of available){for(const item of constituentData.get(code).components){let x=holdings.get(item.symbol);if(!x){x={name:item.name,codes:[],weights:[]};holdings.set(item.symbol,x);}x.codes.push(code);x.weights.push(item.weight);}}
 const common=[...holdings.entries()].filter(([symbol,row])=>row.codes.length>1).sort((a,b)=>Math.min(...b[1].weights)-Math.min(...a[1].weights));
 const hint=missing.length?`<div class="info-box">目前缺少 ${missing.map(esc).join('、')} 的成分股資料，只能對已取得資料的 ETF 進行部分比較。未取得完整資料前，不會顯示「零重疊」或估算全部風險。</div>`:'';
 return `<section class="card"><div class="cardhead"><h2>持股重疊透視</h2><span class="feature-badge">ETF 實際持股</span></div><p class="small" style="margin:12px 0">同一家股票是否同時出現在不同 ETF？依成分股公告日期比較，非盤中即時持股。</p>${hint}${common.length?`<div class="constituent-list">${common.slice(0,20).map(([symbol,row])=>`<div class="constituent-row"><div><b>${esc(row.name)}</b><small>${esc(symbol)} · ${row.codes.map((c,i)=>esc(c)+' '+row.weights[i].toFixed(2)+'%').join('／')}</small></div><strong>${row.codes.length} 檔重疊</strong></div>`).join('')}</div>`:missing.length?'':`<div class="info-box">可用成分股中未發現相同股票；仍須以各檔公告完整性為準。</div>`}<div class="inline-actions">${codes.map(c=>`<a href="#etf/${esc(c)}/components" class="button">${esc(c)} 成分股</a>`).join('')}</div></section>`;
}
function compareBase(){const rows=comparison.map(code=>records().find(e=>e.code===code)||{code,name:'尚未載入／不在本次資料範圍',category:'pending',management:null,index:null});return `${title('ETF 比較')}<p class="small">最多三檔，一次看清基本差異。</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>比較項目</th>${rows.map(e=>`<th><a href="#etf/${e.code}" class="code">${e.code}</a><div class="etf-name">${esc(e.name)}</div><button class="button smallbtn" data-action="compare" data-code="${e.code}">移除</button></th>`).join('')}</tr></thead><tbody><tr><th>目前報價</th>${rows.map(e=>`<td class="quote-slot" data-quote="${e.code}"></td>`).join('')}</tr>${[['主要分類',e=>categoryLabel(e.category)],['管理方式',e=>e.management==='active'?'主動式':e.management==='passive'?'被動式':'待確認'],['追蹤指數',e=>e.index||'不適用／未提供'],['資料日期',e=>e.sourceDate||'待確認'],['配息／費用率',()=> '尚未接入']].map(([label,get])=>`<tr><th>${label}</th>${rows.map(e=>`<td>${esc(get(e))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="inline-actions"><a class="button primary" href="#list">挑選其他 ETF</a>${button('清空比較','clear-compare')}</div>`:empty('先挑兩檔，看看差在哪','進入 ETF 詳情，點「加入比較」。',`<a class="button primary" href="#list">探索 ETF</a>`)}${compareOverlapPanel()}${sourceNote()}`;}
function overlapMarkup(){const selected=comparison.filter(c=>constituentData.has(c));if(comparison.length<2)return '';if(selected.length<2)return `<section class="card"><h2>重疊成分股</h2><div class="info-box">請先取得至少兩檔 ETF 的真實成分股資料，再進行交集分析。不會用猜測的名單補齊。</div></section>`;const maps=selected.map(c=>new Map(constituentData.get(c).components.map(x=>[x.symbol,x]))),same=[...maps[0]].filter(([sym])=>maps.slice(1).every(m=>m.has(sym))).sort((a,b)=>b[1].weight-a[1].weight);return `<section class="card"><h2>共同成分股</h2><p class="small">已取得成分股資料的 ETF：${selected.join('、')}；不同 ETF 公告日期可能不同。</p>${same.length?same.slice(0,40).map(([sym,x],i)=>`<div class="constituent-row"><span><b>${i+1}. ${esc(x.name)}</b><small>${esc(sym)} · ${selected.map((c,j)=>c+' '+maps[j].get(sym).weight.toFixed(2)+'%').join('／')}</small></span><strong>${selected.length} 檔</strong></div>`).join(''):'<p class="small">目前已取得資料中沒有共同股票。</p>'}</section>`;}
function compare(){return compareBase()+overlapMarkup();}
function favoritesPage(){const rows=favorites.map(code=>records().find(e=>e.code===code)||{code,name:'尚未載入／不在本次資料範圍',category:'pending',management:null});return `${title('我的收藏')}<p class="small" style="margin-bottom:15px">${favorites.length} 檔自選，不代表實際持有。</p><div class="list-panel">${rows.length?rows.map(etfRow).join(''):empty('先收藏，慢慢了解','點 ETF 旁邊的星星，即可加入這裡。',`<a class="button" href="#list">探索 ETF</a>`)}</div>`;}
