function about(){return `${title('資料與隱私')}<section class="card"><h2>你的資料留在這台裝置</h2><p class="small" style="margin:12px 0">持有股數、成本、股息與收藏保存在這個瀏覽器。沒有雲端同步，清除網站資料會遺失；請定期匯出完整備份。</p><h3>行情金鑰</h3><p class="small" style="margin:10px 0">個人行情金鑰只在伺服器記憶體暫存，最長六小時，不存入瀏覽器、原始碼或備份；到期或伺服器重啟後需重新連接。App 查詢時會傳送所需證券代碼。</p><h3>資產與股息</h3><p class="small" style="margin:10px 0">持倉市值使用自行填入的參考價，不等於完整總資產；未填價格的部位不當作零。損益不含股息、不含已實現買賣成果。已領股息另外記錄，避免重複加總。</p><h3>名單與分類</h3>${sourceNote()}<p class="small">策略標籤為 App 規則，不能拿來判定適合買進。收益、配息與本金皆不保證；試算僅為自訂情境。</p></section><section class="card"><h3>目前尚未接入</h3><p class="small" style="margin-top:10px">官方配息自動同步、歷史走勢、基金費用率、盤中淨值、跨券商自動同步、雲端同步及背景推播。成分股需來源授權或由使用者匯入。介面不使用假數字或假線圖補齊。</p></section><p class="version">獨立開發版 ${VERSION} · 不使用 Lovable</p>`;}
function renderNav(view){const active=view==='etf'||view==='favorites'||view==='compare'?'list':view==='calendar'?'home':view==='tools'||view==='about'||view==='insights'||view==='brokers'?'more':view;const alerts=portfolioSummary(store(),records()).overdue.length;document.querySelector('#nav').innerHTML=[['home','home','首頁'],['list','search','找 ETF'],['holdings','wallet','持有'],['notifications','bell','配息提醒'],['more','more','更多']].map(([id,i,t])=>`<a href="#${id}" class="${active===id?'current':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='notifications'&&alerts?'<i class="nav-dot"></i>':''}</a>`).join('');const tray=document.querySelector('#compare-tray');tray.hidden=!(comparison.length&&['list','favorites','etf'].includes(view));tray.innerHTML=tray.hidden?'':`<span>已選 ${comparison.length}／3 檔 · ${comparison.join(' / ')}</span><a class="button smallbtn" href="#compare">比較 ${icon('arrow')}</a>`;}
