function renderHolding(){const old=editingId?store().holdings.find(h=>h.id===editingId):null;holdingDialog.innerHTML=`<div class="modal-head"><h2>${editingId?'編輯持有':'新增我的持有'}</h2><button class="iconbtn" data-action="close-holding" aria-label="關閉">${icon('close')}</button></div><div class="step-label">${holdingStep===1?'1 / 2　選擇 ETF':'2 / 2　填入你的持有'}</div>${holdingStep===1?`<p class="small">先選一檔，不需要知道所有投資名詞。</p><label class="searchbox">${icon('search')}<input id="choose-search" type="search" aria-label="搜尋要新增的 ETF" placeholder="搜尋代碼或名稱"></label><div class="choose-list" id="choose-results"></div><button class="button full" data-action="manual-etf" style="margin-top:14px">手動輸入代碼與名稱</button>`:`<form id="guided-holding"><div class="form-grid"><label class="field"><span>ETF 代碼</span><input name="code" required maxlength="20" value="${esc(chosen?.code||'')}" placeholder="0050"></label><label class="field"><span>ETF 名稱</span><input name="name" required maxlength="120" value="${esc(chosen?.name||'')}"></label><label class="field"><span>你持有多少？</span><input name="shares" type="number" inputmode="decimal" required min="0.001" step="any" value="${old?.shares||''}" placeholder="1000"></label><label class="field"><span>單位</span><select name="unit"><option value="shares">股</option><option value="lots">張（1,000 股）</option></select></label><label class="field full"><span>目前持倉總成本（元）</span><input name="cost" type="number" inputmode="decimal" required min="0" step="any" value="${old?.cost??''}" placeholder="填入實際支付金額，含費用"><small>這是目前全部持倉的成本，不是每股價格。</small></label></div><details><summary class="small" style="cursor:pointer;min-height:40px">選填：加入自填參考價格</summary><div class="form-grid"><label class="field"><span>每股參考價格</span><input name="price" type="number" min="0" step="any" inputmode="decimal" value="${old?.price??''}"></label><label class="field"><span>價格日期</span><input name="priceDate" type="date" value="${old?.priceDate||today}"></label></div><p class="tiny">這個價格用於資產估值，不冒充即時行情。</p></details><p class="form-error" role="alert"></p><div class="inline-actions">${!editingId?button('上一步','holding-back'):''}<button class="button primary" type="submit">${icon('check')} 儲存持有</button></div></form>`}`;if(holdingStep===1)holdingChoices();}
holdingDialog.addEventListener('submit',e=>{if(e.target.id!=='guided-holding')return;e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));const h=validateHolding(holdingFromForm(values,editingId||crypto.randomUUID()));const previous=tools.data;tools.data={...previous,holdings:editingId?previous.holdings.map(x=>x.id===editingId?h:x):[...previous.holdings,h]};validateBackup(tools.data);const saved=tools.persist();holdingDialog.close();location.hash='#holdings';route();notify(saved?'持有已儲存。':'目前僅暫存，請立即匯出備份。');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}});
