document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,code,id}=b.dataset;
 if(action==='theme')toggleTheme();else if(action==='privacy'){hideMoney=!hideMoney;document.documentElement.classList.toggle('privacy-hidden',hideMoney);try{localStorage.setItem('etf:privacy',hideMoney?'hide':'show');}catch{}b.setAttribute('aria-pressed',String(hideMoney));}
 else if(action==='favorite'||action==='compare'){const isFav=action==='favorite',list=isFav?favorites:comparison;const removing=list.includes(code);if(!removing&&!records().some(e=>e.code===code)){notify('請先載入這檔 ETF 的名單資料。');return;}if(!isFav&&!removing&&list.length>=3){notify('最多比較三檔，請先移除一檔。');return;}const next=removing?list.filter(x=>x!==code):[...list,code];if(writeList(isFav?'etf:favorites':'etf:compare',next)){if(isFav)favorites=next;else comparison=next;route();notify(isFav?(removing?'已取消收藏':'已加入收藏'):(removing?'已移除比較':'已加入比較'));}}
