 else if(action==='holding-tab'){holdingTab=b.dataset.tab;history.replaceState(null,'','#holdings');route();}else if(action==='calendar-tab'){calendarTab=b.dataset.tab;route();}else if(action==='detail-tab'){detailTab=b.dataset.tab;route();}
 else if(action==='prev-month'||action==='next-month'){const d=new Date(Date.UTC(calYear,calMonth-1+(action==='prev-month'?-1:1),1));calYear=d.getUTCFullYear();calMonth=d.getUTCMonth()+1;selectedDay=`${calYear}-${String(calMonth).padStart(2,'0')}-01`;history.replaceState(null,'','#calendar');route();}else if(action==='day'){selectedDay=b.dataset.date;history.replaceState(null,'','#calendar');route();}
 else if(action==='add-holding'||action==='edit-holding')showHolding(code,id);else if(action==='close-holding')holdingDialog.close();else if(action==='choose-etf'){chosen=records().find(x=>x.code===code);holdingStep=2;renderHolding();}else if(action==='manual-etf'){chosen=null;holdingStep=2;renderHolding();}else if(action==='holding-back'){holdingStep=1;renderHolding();}
