const CACHE='etf-togo-1.4.0';
const BASE=new URL('./',self.location.href);
const FILES=['index.html','manifest.webmanifest','icon-192.png','icon-512.png','brand-mark.svg'].map(p=>new URL(p,BASE).pathname);
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>(k.startsWith('etf-independent-')||k.startsWith('etf-togo-'))&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==self.location.origin||e.request.method!=='GET'||u.pathname.startsWith('/api/')||u.pathname==='/health')return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match(new URL('index.html',BASE).pathname)));return;}if(FILES.includes(u.pathname))e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));});
